using ExperimentLab.Api;
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();
builder.Services.AddCors(o => o.AddDefaultPolicy(p => p.AllowAnyOrigin().AllowAnyMethod().AllowAnyHeader()));
builder.Services.AddSingleton<IExperimentStore, InMemoryExperimentStore>();
builder.Services.AddSingleton<IAgentService, ClaudeAgentService>();
builder.Services.AddSingleton<IKafkaProducer, KafkaProducer>();
builder.Services.AddHostedService<KafkaEventConsumer>();
builder.Services.AddSingleton<IEventGenerator, EventGenerator>();
builder.Services.AddSingleton<IScorecardStore, ScorecardStore>();
builder.Services.AddSingleton<IAnalystAgent, AnalystAgentService>();
var app = builder.Build();
app.UseCors();
app.UseSwagger(); app.UseSwaggerUI();
app.MapGet("/health", () => Results.Ok(new { status = "ok", kafka = "apache-kafka" }));
app.MapPost("/api/experiments/draft", async (CreateExperimentRequest req, IAgentService agent) => Results.Ok(await agent.DesignExperimentAsync(req.Prompt)));
app.MapPost("/api/experiments/validate", async (ExperimentSpec spec, IAgentService agent) => Results.Ok(await agent.ValidateExperimentAsync(spec)));
app.MapPost("/api/experiments", async (ExperimentSpec spec, IExperimentStore store, IKafkaProducer kafka, IAgentService agent) => { var v = await agent.ValidateExperimentAsync(spec); if (!v.Approved) return Results.BadRequest(v); store.Save(spec); await kafka.PublishAsync("experiments.created", spec); return Results.Created($"/api/experiments/{spec.Name}", spec); });
app.MapGet("/api/experiments", (IExperimentStore store) => Results.Ok(store.All()));
app.MapPost("/api/events/generate", async (GenerateEventsRequest req, IEventGenerator gen) => Results.Ok(await gen.GenerateAsync(req.ExperimentName, req.Count)));
app.MapGet("/api/scorecards/{experiment}", (string experiment, IScorecardStore store) => Results.Ok(store.Get(experiment)));
app.MapGet("/api/scorecards", (IScorecardStore store) => Results.Ok(store.All()));
app.MapPost("/api/scorecards/compute", async (string experiment, IScorecardStore store) => Results.Ok(await store.ComputeAsync(experiment)));
app.MapPost("/api/analyst/report", async (string experiment, IScorecardStore store, IExperimentStore expStore, IAnalystAgent analyst) => { var card = store.Get(experiment) ?? await store.ComputeAsync(experiment); var spec = expStore.All().FirstOrDefault(s => s.Name == experiment); return Results.Ok(await analyst.AnalyzeAsync(card, spec)); });
app.MapGet("/api/analyst/report/{experiment}", async (string experiment, IScorecardStore store, IExperimentStore expStore, IAnalystAgent analyst) => { var card = store.Get(experiment) ?? await store.ComputeAsync(experiment); var spec = expStore.All().FirstOrDefault(s => s.Name == experiment); return Results.Ok(await analyst.AnalyzeAsync(card, spec)); });
app.Run();
